#!/bin/sh
# Service-owned (not generated by sdk-kit): runs live/live_test.py against Datadog APM.
# Skips (exit 0) without DATADOG_API_KEY / DATADOG_APP_KEY. Otherwise installs ./python into
# $LIVE_VENV (default live/.venv), starts a datadog/agent container unless GROW_DATADOG_APM_URL or
# DD_AGENT_HOST names a running Agent (live.yml runs the Agent as a job service), runs the suite
# and always removes the container it started. Used by `make -C live live` and live.yml.
set -eu
here=$(cd "$(dirname "$0")" && pwd)
root=$(dirname "$here")
python=${PYTHON:-python3}
venv=${LIVE_VENV:-.venv}
case "$venv" in /*) ;; *) venv="$here/$venv" ;; esac
# Same Agent build as the Docker suite (docker/compose.service.yml).
agent_image=${LIVE_AGENT_IMAGE:-datadog/agent:7.85.4@sha256:d0df2a5f7dcda4f702a1d47ef9bd25bdf772421140ef964537562d906129260a}

rc=0
"$python" "$here/live_test.py" --check-credentials || rc=$?
[ "$rc" -eq 78 ] && exit 0
[ "$rc" -eq 0 ] || exit "$rc"

[ -x "$venv/bin/python" ] || "$python" -m venv "$venv"
"$venv/bin/python" -m pip install --quiet --disable-pip-version-check "$root/python"

if [ -z "${GROW_DATADOG_APM_URL:-}" ] && [ -z "${DD_AGENT_HOST:-}" ] && [ -z "${DD_TRACE_AGENT_URL:-}" ]; then
  suffix=$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom 2>/dev/null | head -c 8)
  name="grow-live-datadog-agent-${suffix:-$$}"
  cleanup() { docker rm -f "$name" >/dev/null 2>&1 || true; }
  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  echo "==> starting $agent_image as $name (site ${DATADOG_SITE:-datadoghq.eu})"
  # The key reaches the container through the environment, never the command line.
  DD_API_KEY="$DATADOG_API_KEY" DD_SITE="${DATADOG_SITE:-datadoghq.eu}" docker run -d --name "$name" \
    -e DD_API_KEY -e DD_SITE \
    -e DD_HOSTNAME=grow-sdk-live-local \
    -e DD_APM_ENABLED=true -e DD_APM_NON_LOCAL_TRAFFIC=true \
    -e DD_OTLP_CONFIG_RECEIVER_PROTOCOLS_HTTP_ENDPOINT=0.0.0.0:4318 \
    -e DD_OTLP_CONFIG_LOGS_ENABLED=false -e DD_LOGS_ENABLED=false \
    -e DD_PROCESS_CONFIG_PROCESS_COLLECTION_ENABLED=false \
    -e DD_PROCESS_CONFIG_CONTAINER_COLLECTION_ENABLED=false \
    -e DD_REMOTE_CONFIGURATION_ENABLED=false -e DD_INVENTORIES_ENABLED=false \
    -e DD_ENABLE_METADATA_COLLECTION=false -e DD_AUTOCONFIG_FROM_ENVIRONMENT=false \
    -e DD_LOG_LEVEL=warn \
    -p 127.0.0.1::8126 -p 127.0.0.1::4318 \
    "$agent_image" >/dev/null
  trace_port=$(docker port "$name" 8126/tcp | head -n 1 | sed 's/.*://')
  otlp_port=$(docker port "$name" 4318/tcp | head -n 1 | sed 's/.*://')
  export GROW_DATADOG_APM_URL="http://127.0.0.1:$trace_port"
  export GROW_DATADOG_APM_OTLP_ENDPOINT="http://127.0.0.1:$otlp_port"
  # The suite itself waits (up to 90 s) for the Agent's /info to answer.
  rc=0
  "$venv/bin/python" "$here/live_test.py" || rc=$?
  if [ "$rc" -ne 0 ]; then
    echo "==> Agent log (last 40 lines)"
    docker logs --tail 40 "$name" 2>&1 || true
  fi
  exit "$rc"
fi
"$venv/bin/python" "$here/live_test.py"
